public class OverdueInvoiceBatch implements Database.Batchable<sObject> {

    // Running totals that must accumulate across every chunk of the job.
    private Integer recordsUpdated = 0;
    private Integer recordsFailed = 0;
    private Decimal overdueAmount = 0.0;

    public OverdueInvoiceBatch() {
        recordsUpdated = 0;
        recordsFailed = 0;
        overdueAmount = 0.0;
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = 'Open'
              AND Due_Date__c < TODAY
        ]);
    }

    public void execute(Database.BatchableContext bc, List<sObject> scope) {
        List<FB_Invoice__c> invoices = (List<FB_Invoice__c>) scope;
        if (invoices == null || invoices.isEmpty()) {
            return;
        }

        // Capture the amount for each record BEFORE the update so we can
        // attribute Amount__c to records that actually succeed.
        Map<Id, Decimal> amountById = new Map<Id, Decimal>();
        for (FB_Invoice__c inv : invoices) {
            inv.Status__c = 'Overdue';
            Decimal amt = (inv.Amount__c == null) ? 0.0 : inv.Amount__c;
            amountById.put(inv.Id, amt);
        }

        // Partial success (allOrNone = false) so a single validation-rule
        // failure does not roll back the rest of the chunk.
        List<Database.SaveResult> results = Database.update(invoices, false);

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results.get(i);
            if (sr != null && sr.isSuccess()) {
                recordsUpdated++;
                Decimal amt = amountById.get(invoices.get(i).Id);
                if (amt != null) {
                    overdueAmount += amt;
                }
            } else {
                recordsFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c();
        summary.Job_Name__c = 'OverdueInvoiceBatch';
        summary.Records_Updated__c = recordsUpdated;
        summary.Records_Failed__c = recordsFailed;
        summary.Overdue_Amount__c = overdueAmount;
        insert summary;
    }
}
