public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ── Validate scalar parameters ──────────────────────────────────
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200');
        }

        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields cannot be null or empty');
        }

        if (String.isBlank(objectApiName)) {
            throw new SearchException('objectApiName cannot be blank');
        }

        // ── Resolve object (case-insensitive) ───────────────────────────
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        String resolvedObjName = null;
        Schema.SObjectType objType = null;

        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                resolvedObjName = key;
                objType = globalDescribe.get(key);
                break;
            }
        }

        if (objType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        // ── Object-level FLS check ──────────────────────────────────────
        Schema.DescribeSObjectResult objDesc = objType.getDescribe();
        if (!objDesc.isAccessible()) {
            throw new SearchException('Running user cannot read object: ' + resolvedObjName);
        }

        Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();

        // ── Check FLS on Id (always selected) ───────────────────────────
        if (!fieldMap.get('Id').getDescribe().isAccessible()) {
            throw new SearchException('Running user cannot read field: Id');
        }

        // ── Resolve SELECT fields (case-insensitive, deduplicated) ──────
        List<String> selectFields = new List<String>();
        Set<String> seenResolved = new Set<String>();

        for (String raw : fields) {
            if (String.isBlank(raw)) {
                throw new SearchException('Field name cannot be blank');
            }
            String resolved = resolveField(fieldMap, raw);
            Schema.DescribeFieldResult fldDesc = fieldMap.get(resolved).getDescribe();
            if (!fldDesc.isAccessible()) {
                throw new SearchException(
                    'Running user cannot read field: ' + resolved
                );
            }
            if (resolved.equalsIgnoreCase('Id')) {
                continue;
            }
            if (!seenResolved.contains(resolved)) {
                seenResolved.add(resolved);
                selectFields.add(resolved);
            }
        }

        // ── Resolve ORDER BY field ──────────────────────────────────────
        String resolvedOrder = null;
        if (String.isNotBlank(orderByField)) {
            resolvedOrder = resolveField(fieldMap, orderByField);
            Schema.DescribeFieldResult orderDesc = fieldMap.get(resolvedOrder).getDescribe();
            if (!orderDesc.isAccessible()) {
                throw new SearchException(
                    'Running user cannot read field: ' + resolvedOrder
                );
            }
            if (!orderDesc.isSortable()) {
                throw new SearchException(
                    'Field cannot be used for ORDER BY: ' + resolvedOrder
                );
            }
        }

        // ── Build the SOQL query ────────────────────────────────────────
        List<String> selectList = new List<String>{'Id'};
        selectList.addAll(selectFields);

        String query = 'SELECT ' + String.join(selectList, ', ') + ' FROM ' + resolvedObjName;

        // ── WHERE clause (safe against SOQL injection) ──────────────────
        if (filters != null && !filters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String rawKey : filters.keySet()) {
                if (String.isBlank(rawKey)) {
                    throw new SearchException('Filter field name cannot be blank');
                }
                String resolvedFilter = resolveField(fieldMap, rawKey);
                Schema.DescribeFieldResult filterDesc = fieldMap.get(resolvedFilter).getDescribe();
                if (!filterDesc.isAccessible()) {
                    throw new SearchException(
                        'Running user cannot read field: ' + resolvedFilter
                    );
                }
                if (!filterDesc.isFilterable()) {
                    throw new SearchException(
                        'Field cannot be used in a filter: ' + resolvedFilter
                    );
                }
                String literal = toSoqlLiteral(filters.get(rawKey), filterDesc.getType());
                conditions.add(resolvedFilter + ' = ' + literal);
            }
            query += ' WHERE ' + String.join(conditions, ' AND ');
        }

        // ── ORDER BY ────────────────────────────────────────────────────
        if (resolvedOrder != null) {
            query += ' ORDER BY ' + resolvedOrder + ' ASC';
        }

        // ── LIMIT ───────────────────────────────────────────────────────
        query += ' LIMIT ' + String.valueOf(maxRows);

        // ── Execute (class is "with sharing", so record sharing is enforced) ─
        List<SObject> results;
        try {
            results = Database.query(query);
        } catch (Exception ex) {
            throw new SearchException('Query execution failed: ' + ex.getMessage());
        }

        return results;
    }

    // ────────────────────────────────────────────────────────────────────
    // Private helpers
    // ────────────────────────────────────────────────────────────────────

    /**
     * Case-insensitively resolves a field name against the object's field map.
     * Throws SearchException when the field is not found.
     */
    private static String resolveField(Map<String, Schema.SObjectField> fieldMap, String name) {
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(name)) {
                return key;
            }
        }
        throw new SearchException('Field does not exist: ' + name);
    }

    /**
     * Converts a filter value to a SOQL-safe literal, deciding the format based on
     * the FIELD TYPE (not the runtime value type) so that values of any type are
     * emitted correctly and safely (escapeSingleQuotes for anything quoted).
     */
    private static String toSoqlLiteral(Object value, Schema.FieldType fieldType) {
        if (value == null) {
            return 'null';
        }

        // Types that require a quoted (string) literal in SOQL.
        Boolean mustQuote = (
            fieldType == Schema.FieldType.STRING ||
            fieldType == Schema.FieldType.ID ||
            fieldType == Schema.FieldType.REFERENCE ||
            fieldType == Schema.FieldType.COMBINATOR ||
            fieldType == Schema.FieldType.PICKLIST ||
            fieldType == Schema.FieldType.MULTISELECTPICKLIST ||
            fieldType == Schema.FieldType.ENCRYPTEDSTRING ||
            fieldType == Schema.FieldType.TIME
        );

        if (mustQuote) {
            return '\'' + String.escapeSingleQuotes(String.valueOf(value)) + '\'';
        }

        // Boolean field.
        if (fieldType == Schema.FieldType.BOOLEAN) {
            return (value instanceof Boolean) ? ((Boolean) value ? 'true' : 'false')
                                              : String.valueOf(value);
        }

        // Date field.
        if (fieldType == Schema.FieldType.DATE) {
            if (value instanceof Date) {
                return String.valueOf(value);
            }
            if (value instanceof DateTime) {
                return ((DateTime) value).formatGmt('yyyy-MM-dd');
            }
            // String or numeric: pass through; if malformed SOQL errors -> SearchException.
            return String.valueOf(value);
        }

        // DateTime field.
        if (fieldType == Schema.FieldType.DATETIME) {
            if (value instanceof DateTime) {
                return ((DateTime) value).formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'');
            }
            if (value instanceof Date) {
                return String.valueOf(value) + 'T00:00:00Z';
            }
            return String.valueOf(value);
        }

        // Numeric fields (Integer/Long/Decimal/Double/Currency).
        if (
            fieldType == Schema.FieldType.INT ||
            fieldType == Schema.FieldType.INTEGER ||
            fieldType == Schema.FieldType.LONG ||
            fieldType == Schema.FieldType.DECIMAL ||
            fieldType == Schema.FieldType.DOUBLE ||
            fieldType == Schema.FieldType.CURRENCY
        ) {
            if (value instanceof Integer || value instanceof Long ||
                value instanceof Decimal || value instanceof Double) {
                return String.valueOf(value);
            }
            // Non-numeric passed to a numeric field: emit raw (syntax error -> SearchException).
            return String.valueOf(value);
        }

        // Default: quote and escape everything else for safety.
        return '\'' + String.escapeSingleQuotes(String.valueOf(value)) + '\'';
    }
}
