public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = Decimal.valueOf(0);
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount = Decimal.valueOf(0);
        public Decimal lineTotal = Decimal.valueOf(0);
    }

    // ---------- parsing helpers ----------

    private static Decimal toDecimal(Object val) {
        if (val == null) return null;
        if (val instanceof Decimal) return (Decimal) val;
        if (val instanceof Integer) return Decimal.valueOf((Integer) val);
        if (val instanceof Long) return Decimal.valueOf((Long) val);
        if (val instanceof Double) return Decimal.valueOf((Double) val);
        if (val instanceof String) {
            String s = (String) val;
            if (String.isBlank(s)) return null;
            try { return Decimal.valueOf(s); }
            catch (Exception e) { return null; }
        }
        return null;
    }

    // ---------- parse ----------

    public static OrderPayloadParser.Order parse(String body) {
        if (body == null || String.isBlank(body)) {
            throw new OrderPayloadParser.PayloadException('Body must not be null or blank');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        }
        catch (Exception e) {
            throw new OrderPayloadParser.PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new OrderPayloadParser.PayloadException('JSON body must be a JSON object');
        }

        Map<String, Object> fields = (Map<String, Object>) root;
        OrderPayloadParser.Order order = new OrderPayloadParser.Order();

        // number - required
        Object numberVal = fields.get('number');
        String numberStr = (numberVal instanceof String) ? (String) numberVal :
                           (numberVal == null ? null : String.valueOf(numberVal));
        if (!fields.containsKey('number') || numberVal == null || String.isBlank(numberStr)) {
            throw new OrderPayloadParser.PayloadException('Missing or blank "number"');
        }
        order.orderNumber = numberStr;

        // date - optional ISO yyyy-MM-dd
        Object dateVal = fields.get('date');
        if (dateVal instanceof String) {
            String dateStr = (String) dateVal;
            if (!String.isBlank(dateStr)) {
                List<String> parts = dateStr.split('-');
                if (parts.size() == 3) {
                    try {
                        order.orderDate = Date.newDate(
                            Integer.valueOf(parts[0]),
                            Integer.valueOf(parts[1]),
                            Integer.valueOf(parts[2])
                        );
                    }
                    catch (Exception ignore) {
                        order.orderDate = null;
                    }
                }
            }
        }

        // currency - optional
        Object currencyVal = fields.get('currency');
        if (currencyVal instanceof String) {
            order.currencyCode = (String) currencyVal;
        } else if (currencyVal != null) {
            order.currencyCode = String.valueOf(currencyVal);
        }

        // customer - optional
        Object customerVal = fields.get('customer');
        if (customerVal instanceof Map<String, Object>) {
            Object emailVal = ((Map<String, Object>) customerVal).get('email');
            if (emailVal instanceof String) {
                order.customerEmail = (String) emailVal;
            }
        }

        // lines - optional, empty list when missing/null
        Object linesVal = fields.get('lines');
        if (linesVal instanceof List<Object>) {
            List<Object> lineList = (List<Object>) linesVal;
            Decimal orderTotal = Decimal.valueOf(0);

            for (Object item : lineList) {
                if (!(item instanceof Map<String, Object>)) {
                    continue; // ignore unknown/unexpected line entries
                }
                Map<String, Object> lm = (Map<String, Object>) item;
                Line line = new Line();

                // sku - missing throws
                Object skuVal = lm.get('sku');
                if (!lm.containsKey('sku') || skuVal == null ||
                    (skuVal instanceof String && String.isBlank((String) skuVal))) {
                    throw new OrderPayloadParser.PayloadException('Line is missing "sku"');
                }
                line.sku = (skuVal instanceof String) ? (String) skuVal : String.valueOf(skuVal);

                // quantity - missing or non-positive throws
                if (!lm.containsKey('quantity') || lm.get('quantity') == null) {
                    throw new OrderPayloadParser.PayloadException('Line is missing "quantity"');
                }
                Decimal qtyD = toDecimal(lm.get('quantity'));
                if (qtyD == null || qtyD <= 0) {
                    throw new OrderPayloadParser.PayloadException('Line quantity must be a positive number');
                }
                line.quantity = qtyD.intValue();

                // unitPrice - missing or negative throws
                if (!lm.containsKey('unitPrice') || lm.get('unitPrice') == null) {
                    throw new OrderPayloadParser.PayloadException('Line is missing "unitPrice"');
                }
                Decimal priceD = toDecimal(lm.get('unitPrice'));
                if (priceD == null || priceD < 0) {
                    throw new OrderPayloadParser.PayloadException('Line unitPrice must be a non-negative number');
                }
                line.unitPrice = priceD;

                // discount - missing/null => 0, fraction [0,1]
                Decimal discD = Decimal.valueOf(0);
                Object discVal = lm.get('discount');
                if (discVal != null) {
                    Decimal parsed = toDecimal(discVal);
                    if (parsed != null) {
                        // clamp to [0,1] to honor "fraction between 0 and 1"
                        if (parsed < 0) parsed = Decimal.valueOf(0);
                        if (parsed > 1) parsed = Decimal.valueOf(1);
                        discD = parsed;
                    }
                }
                line.discount = discD;

                Decimal qtyFactor = Decimal.valueOf(line.quantity);
                Decimal raw = qtyFactor.multiply(line.unitPrice.multiply((Decimal.valueOf(1).subtract(discD))));
                line.lineTotal = raw.setScale(2, System.RoundingMode.HALF_UP);

                order.lines.add(line);
                orderTotal = orderTotal.add(line.lineTotal);
            }

            order.total = orderTotal;
        } else {
            order.total = Decimal.valueOf(0);
        }

        if (order.total == null) {
            order.total = Decimal.valueOf(0);
        }

        return order;
    }

    // ---------- acknowledgement ----------

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order == null ? null : order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', (order == null || order.lines == null) ? 0 : order.lines.size());
        ack.put('total', (order == null || order.total == null) ? Decimal.valueOf(0) : order.total);

        // serialize so that key/value order is stable if desired; order is not required.
        return JSON.serialize(ack);
    }
}
