/**
 * Tests for AddressVerificationService.
 *
 * Covers:
 *  - Blank/null BillingStreet short-circuits (SKIPPED, no callout).
 *  - POST callout contract (method, endpoint, headers, JSON body).
 *  - 200 responses: VERIFIED / INVALID leave the account untouched,
 *    CORRECTED rewrites the account's billing fields in memory.
 *  - Non-200 responses throw AddressVerificationException with the status code.
 */
@IsTest
private class AddressVerificationServiceTest {

    /* ---------------------------------------------------------------- */
    /* Mock: captures the outgoing request and returns a configured resp */
    /* ---------------------------------------------------------------- */
    private class MockAddressApi implements HttpCalloutMock {
        public HttpRequest request;
        public Integer calloutCount = 0;
        private final Integer statusCode;
        private final String responseBody;

        public MockAddressApi(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest req) {
            this.request = req;
            this.calloutCount++;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(this.statusCode);
            if (this.responseBody != null) {
                res.setBody(this.responseBody);
            }
            return res;
        }
    }

    /* ---------------------------------------------------------------- */
    /* Helpers                                                           */
    /* ---------------------------------------------------------------- */
    private static MockAddressApi installMock(Integer status, String body) {
        MockAddressApi mock = new MockAddressApi(status, body);
        Test.setMock(HttpCalloutMock.class, mock);
        return mock;
    }

    private static void assertRequestContract(Account acct, MockAddressApi mock) {
        System.assertNotEquals(null, mock.request, 'A callout should have been made');
        System.assertEquals(1, mock.calloutCount, 'Exactly one callout expected');
        System.assertEquals('POST', mock.request.getMethod(),
                'The service must use the POST verb');
        System.assertEquals('callout:FB_Address_API/v2/verify', mock.request.getEndpoint(),
                'The endpoint must use the FB_Address_API named credential at /v2/verify');
        System.assertEquals('application/json', mock.request.getHeader('Content-Type'),
                'Content-Type must be application/json');

        Map<String, Object> body = (Map<String, Object>)
                JSON.deserializeUntyped(mock.request.getBody());
        System.assertEquals(acct.BillingStreet, (String) body.get('street'),
                'body.street must match BillingStreet');
        System.assertEquals(acct.BillingCity, (String) body.get('city'),
                'body.city must match BillingCity');
        System.assertEquals(acct.BillingPostalCode, (String) body.get('postalCode'),
                'body.postalCode must match BillingPostalCode');
        System.assertEquals(acct.BillingCountry, (String) body.get('country'),
                'body.country must match BillingCountry');
    }

    private static Account makeAccount() {
