public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException(
                'Object and field API names are required and must not be null or blank.'
            );
        }

        // --- Locate the SObjectType (case-insensitive) ---
        Map<String, Schema.SObjectType> globalDesc = Schema.getGlobalDescribe();
        Schema.SObjectType sType = null;
        for (String key : globalDesc.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                sType = globalDesc.get(key);
                break;
            }
        }

        if (sType == null) {
            throw new PicklistServiceException(
                'Object does not exist: ' + objectApiName
            );
        }

        // --- Locate the SObjectField (case-insensitive) ---
        Map<String, Schema.SObjectField> fieldMap =
            sType.getDescribe().fields.getMap();
        Schema.SObjectField sField = null;
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                sField = fieldMap.get(key);
                break;
            }
        }

        if (sField == null) {
            throw new PicklistServiceException(
                'Field does not exist on ' + objectApiName + ': ' + fieldApiName
            );
        }

        Schema.FieldDescribeResult fieldDesc = sField.getDescribe();

        // --- Validate field type ---
        Schema.DisplayType dtype = fieldDesc.getType();
        if (dtype != Schema.DisplayType.Picklist &&
            dtype != Schema.DisplayType.MultiselectPicklist) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' is not a picklist or multi-select picklist.'
            );
        }

        // --- Build the ordered list of active options ---
        List<Option> options = new List<Option>();

        // getPicklistValues() returns entries in defined order (including inactive)
        for (Schema.PicklistEntry entry : fieldDesc.getPicklistValues()) {
            if (!entry.isActive()) {
                continue;
            }
            Option opt = new Option();
            opt.value     = entry.getValue();
            opt.label     = entry.getLabel();
            opt.isDefault = entry.isDefaultValue();
            options.add(opt);
        }

        return options;
    }
}
