public with sharing class ShipmentEventHandler {

    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Build a map keyed by upper-cased order number; Map.put keeps the last value,
        // so when multiple events reference the same order the last one in the list wins.
        Map<String, FB_Shipment_Event__e> lastEventByOrder = new Map<String, FB_Shipment_Event__e>();
        for (FB_Shipment_Event__e evt : events) {
            if (String.isNotBlank(evt.Order_Number__c)) {
                String key = evt.Order_Number__c.toUpperCase();
                lastEventByOrder.put(key, evt);
            }
        }

        if (lastEventByOrder.isEmpty()) {
            return;
        }

        // Single SOQL query to find matching orders
        Map<String, FB_Sales_Order__c> ordersByOrderNumber = new Map<String, FB_Sales_Order__c>();
        Set<String> orderNumbers = lastEventByOrder.keySet();
        for (FB_Sales_Order__c order : [
            SELECT Id, Order_Number__c, Status__c, Tracking_Number__c, Carrier__c, Shipped_Date__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :orderNumbers
        ]) {
            ordersByOrderNumber.put(order.Order_Number__c.toUpperCase(), order);
        }

        // Determine which orders need updating
        List<FB_Sales_Order__c> toUpdate = new List<FB_Sales_Order__c>();
        Date today = Date.today();

        for (String orderNumber : lastEventByOrder.keySet()) {
            FB_Sales_Order__c order = ordersByOrderNumber.get(orderNumber);
            if (order == null) {
                continue; // Unknown order number - ignore
            }
            if (order.Status__c == 'Cancelled') {
                continue; // Cancelled orders are never changed
            }
            FB_Shipment_Event__e evt = lastEventByOrder.get(orderNumber);
            order.Status__c = 'Shipped';
            order.Tracking_Number__c = evt.Tracking_Number__c;
            order.Carrier__c = evt.Carrier__c;
            order.Shipped_Date__c = today;
            toUpdate.add(order);
        }

        // Single DML statement
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
