public class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach finalizer for this transaction / job
        Finalizer[] finalizers = new Finalizer[]{
            new ErpSyncFinalizer(this.accountIds, this.attempt)
        };
        // Transaction-level finalizer registration (framework handles invocation)
        System.attachments(finalizers);

        List<Account> accounts = new List<Account>();
        for (Account a : [SELECT Id FROM Account WHERE Id IN :this.accountIds]) {
            a.Description = 'Synced to ERP';
            accounts.add(a);
        }
        Database.update(accounts, true);
    }
}
