public with sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    public LogPurgeJob() {}

    /**
     * Schedules the nightly log purge at 02:00 every day.
     * @return the System.Schedule job Id
     */
    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }

    // ── Schedulable ──────────────────────────────────────────────────
    public void execute(SchedulableContext sc) {
        Database.executeBatch(this, 50);
    }

    // ── Database.Batchable ───────────────────────────────────────────
    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime thirtyDaysAgo    = Datetime.now().addDays(-30);
        Datetime oneEightyDaysAgo = Datetime.now().addDays(-180);

        // Non-ERROR (including blank/null): delete if older than 30 days.
        // ERROR:                            delete if older than 180 days.
        return Database.getQueryLocator([
            SELECT Id
