@IsTest
private class RenewalServiceTest {
    private static fflib_ApexMocks mocks;
    private static IOpportunitiesSelector selectorMock;
    private static fflib_ISObjectUnitOfWork uowMock;

    @TestSetup
    static void setup() {
        mocks = new fflib_ApexMocks();
        selectorMock = (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        Application.Selector.setMock(selectorMock);
        uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(uowMock);
    }

    private static Id newId(Schema.SObjectType t) {
        return fflib_IDGenerator.generate(t);
    }

    private static void stubSelector(List<Opportunity> results, Set<Id> ids) {
        mocks.when(selectorMock.selectById(mocks.eq(ids))).thenReturn(results);
    }

    private static void assertRenewalFields(Opportunity renewal, Opportunity src) {
        System.assert(renewal instanceof Opportunity);
        Opportunity r = (Opportunity) renewal;
        System.assertEquals(src.Name + ' - Renewal', r.Name);
        System.assertEquals(src.AccountId, r.AccountId);
        System.assertEquals('Prospecting', r.StageName);
        System.assertEquals(src.CloseDate.addYears(1), r.CloseDate);
        if (src.Amount == null) {
            System.assertEquals(null, r.Amount);
        } else {
            System.assertEquals((src.Amount * RenewalService.UPLIFT).setScale(2), r.Amount);
        }
    }

    @IsTest
    static void nullIds_noWork() {
        RenewalService.createRenewals(null);
        mocks.verify(uowMock, mocks.never()).registerNew((SObject) mocks.anySObject());
        mocks.verify(uowMock, mocks.never()).registerNew(
            (SObject) mocks.anySObject(), (SObjectField) mocks.any(SObjectField.class), (SObject) mocks.anySObject());
        mocks.verify(uowMock, mocks.never()).commitWork();
    }

    @IsTest
    static void emptyIds_noWork() {
        RenewalService.createRenewals(new Set<Id>());
        mocks.verify(uowMock, mocks.never()).registerNew((SObject) mocks.anySObject());
        mocks.verify(uowMock, mocks.never()).commitWork();
    }

    @IsTest
    static void onlyClosedWonWithCloseDateAreRenewed() {
        Id oppWonId = newId(Opportunity.SObjectType);
        Id oppLostId = newId(Opportunity.SObjectType);
        Id oppNoDateId = newId(Opportunity.SObjectType);
        Id oppNoAmountId = newId(Opportunity.SObjectType);
        Id acctId = newId(Account.SObjectType);
        Id ownerId = newId(User.SObjectType);

        Set<Id> ids = new Set<Id>{ oppWonId, oppLostId, oppNoDateId, oppNoAmountId };
        List<Opportunity> results = new List<Opportunity>{
            new Opportunity(Id = oppWonId, Name = 'Won Opp', AccountId = acctId,
                OwnerId = ownerId, StageName = 'Closed Won',
                CloseDate = Date.valueOf('2024-06-15'), Amount = 1000),
            new Opportunity(Id = oppLostId, Name = 'Lost Opp', AccountId = acctId,
                OwnerId = ownerId, StageName = 'Closed Lost',
                CloseDate = Date.valueOf('2024-05-01'), Amount = 500),
            new Opportunity(Id = oppNoDateId, Name = 'NoDate Opp', AccountId = acctId,
                OwnerId = ownerId, StageName = 'Closed Won',
                CloseDate = null, Amount = 500),
            new Opportunity(Id = oppNoAmountId, Name = 'NoAmount Opp', AccountId = acctId,
                OwnerId = ownerId, StageName = 'Closed Won',
                CloseDate = Date.valueOf('2024-04-01'), Amount = null)
        };
        stubSelector(results, ids);

        RenewalService.createRenewals(ids);

        // Capture single-arg registerNew calls (the renewal opportunities)
        ArgumentCaptor<SObject> renewalsCaptor = ArgumentCaptor.forClass(SObject.class);
        mocks.verify(uowMock, mocks.times(2)).registerNew(renewalsCaptor.capture());
        List<SObject> renewals = renewalsCaptor.getAllValues();
        System.assertEquals(2, renewals.size());

        Map<Id, Opportunity> byName = new Map<Id, Opportunity>();
        for (SObject so : renewals) {
            Opportunity r = (Opportunity) so;
            byName.put(r.AccountId, r); // both renewals share account; we use Name below instead
        }

        // Identify by Name suffix
        Opportunity renewalWon = null;
        Opportunity renewalNoAmount = null;
        for (SObject so : renewals) {
            Opportunity r = (Opportunity) so;
            if (r.Name == 'Won Opp - Renewal') renewalWon = r;
            else if (r.Name == 'NoAmount Opp - Renewal') renewalNoAmount = r;
        }
        System.assertNotEquals(null, renewalWon);
        System.assertNotEquals(null, renewalNoAmount);
        assertRenewalFields(renewalWon, results[0]);
        assertRenewalFields(renewalNoAmount, results[3]);

        // Capture task registerNew calls
        ArgumentCaptor<SObject> taskCaptor = ArgumentCaptor.forClass(SObject.class);
        ArgumentCaptor<SObjectField> fieldCaptor = ArgumentCaptor.forClass(SObjectField.class);
        ArgumentCaptor<SObject> relatedCaptor = ArgumentCaptor.forClass(SObject.class);
        mocks.verify(uowMock, mocks.times(2)).registerNew(
            taskCaptor.capture(), fieldCaptor.capture(), relatedCaptor.capture());
        List<SObject> tasks = taskCaptor.getAllValues();
        List<SObjectField> fields = fieldCaptor.getAllValues();
        List<SObject> relateds = relatedCaptor.getAllValues();

        System.assertEquals(2, tasks.size());
        for (Integer i = 0; i < tasks.size(); i++) {
            System.assertEquals(Task.WhatId, fields[i]);
            Task t = (Task) tasks[i];
            // Related object must be the NEW renewal, not the original opportunity
            SObject rel = relateds[i];
            System.assert(rel instanceof Opportunity);
            Opportunity relOpp = (Opportunity) rel;
            System.assertEquals('Prospecting', relOpp.StageName);
            System.assert(relOpp.Name.endsWith(' - Renewal'));

            // Match task to source by checking expected subject fields
            if (t.Subject == 'Prepare renewal for Won Opp') {
                System.assertEquals('Won Opp'.length() > 0, true);
                System.assertEquals(ownerId, t.OwnerId);
                System.assertEquals(Date.valueOf('2024-06-15').addYears(1).addDays(-60), t.ActivityDate);
                System.assertEquals(results[0].OwnerId, t.OwnerId);
            } else {
                System.assertEquals('Prepare renewal for NoAmount Opp', t.Subject);
                System.assertEquals(results[3].OwnerId, t.OwnerId);
                System.assertEquals(Date.valueOf('2024-04-01').addYears(1).addDays(-60), t.ActivityDate);
            }
        }

        // commitWork called exactly once
        mocks.verify(uowMock, mocks.times(1)).commitWork();
    }

