public with sharing class Application {

    public static fflib_Application.UnitOfWorkFactory UnitOfWork { get; set; }
    public static fflib_Application.ServiceFactory Service { get; set; }
    public static fflib_Application.SelectorFactory Selector { get; set; }
    public static fflib_Application.DomainFactory Domain { get; set; }

    static {
        // Unit of Work: registering Account, Contact, Opportunity and OpportunityContactRole
        // so that a single commit can insert Accounts, their Contacts, their Opportunities,
        // and OpportunityContactRoles linking them with all relationships tracked.
        UnitOfWork = new fflib_Application.UnitOfWorkFactory(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            }
        );

        // Service: IAccountsService is implemented by AccountsServiceImpl.
        Service = new fflib_Application.ServiceFactory(
            new Map<Type, Type>{
                IAccountsService.class => AccountsServiceImpl.class
            }
        );

        // Selector: Account records are read by AccountsSelector, Contact records by ContactsSelector.
        Selector = new fflib_Application.SelectorFactory(
            new Map<Schema.SObjectType, Type>{
                Account.SObjectType => AccountsSelector.class,
                Contact.SObjectType => ContactsSelector.class
            }
        );

        // Domain: Account records are wrapped by the Accounts domain.
        // Domain.newInstance(Set<Id>) queries via the Selector factory, then wraps
        // the results using Accounts.Constructor (which implements IConstructable).
        Domain = new fflib_Application.DomainFactory(
            new Map<Schema.SObjectType, Type>{
                Account.SObjectType => Accounts.Constructor.class
            }
        );
    }
}
