public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public Opportunities construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public Opportunities(List<SObject> records) {
        super(records);
    }

    private Set<Id> qualifyingIds = new Set<Id>();

    public override void onBeforeInsert() {
        for (SObject record : records) {
            Opportunity opp = (Opportunity) record;
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
    }

    public override void onAfterInsert() {
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service =
                (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(new Set<Id>(qualifyingIds));
        }
    }

    public void onBeforeUpdate() {
        Map<Id, Opportunity> oldMap = (Map<Id, Opportunity>) Trigger.oldMap;
        for (SObject record : records) {
            Opportunity opp = (Opportunity) record;
            if (opp.StageName == 'Closed Won' && oldMap.get(opp.Id).StageName != 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
    }

    public void onAfterUpdate() {
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service =
                (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(new Set<Id>(qualifyingIds));
        }
    }
}
