        public fflib_IInstances newInstance(SObject exampleSObject, Map<SObjectField, SObjectField> fieldDependencies) {
            return new Accounts(new List<Account> { (Account) exampleSObject });
        }
        public fflib_IInstances newInstance(List<SObject> records) {
            return new Accounts((List<Account>) records);
        }
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public Type getType() {
        return Account.class;
    }

    public List<Account> getAccounts() {
        return (List<Account>) getRecords();
    }

    public IAccounts selectByRating(String rating) {
        List<Account> matching = new List<Account>();
        for (Account record : getAccounts()) {
            if (record.Rating == rating) {
                matching.add(record);
            }
        }
        return newInstance(matching);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account record : getAccounts()) {
            if (record.OwnerId != null) {
                ownerIds.add(record.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account record : getAccounts()) {
            record.Rating = rating;
        }
