/**
 * @description
 *   Selector for the Opportunity SObject. Uses the fflib QueryFactory so that the
 *   selector's standard field list and its security configuration (WITH SECURITY_ENFORCED
 *   etc.) are always honoured, regardless of which method is invoked.
 */
public inherited sharing class OpportunitiesSelector extends fflib_SObjectSelector {

    public Schema.SObjectType getSObjectType() {
        return Opportunity.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Opportunity.Id,
            Opportunity.Name,
            Opportunity.AccountId,
            Opportunity.StageName,
            Opportunity.Amount,
            Opportunity.CloseDate
        };
    }

    public List<Opportunity> selectById(Set<Id> opportunityIds) {
        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * @description
     *   Returns the open (IsClosed = false) opportunities for the supplied accounts,
     *   ranked by Amount descending. Opportunities with no Amount sort after the
     *   populated ones, and rows with an equal Amount are ordered by CloseDate
     *   ascending (earliest first). At most `maxRecords` rows are returned, produced by
     *   a single SOQL query built through the selector's QueryFactory (so the standard
     *   field list + security settings still apply). The parent Account's Name is added
     *   to the projection on top of the standard selector field list.
     *
     * @param accountIds  Accounts whose open opportunities should be considered.
     * @param maxRecords  Maximum number of opportunities to return.
     * @return           List of open Opportunity records, possibly fewer than maxRecords.
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Nothing to do / no rows allowed -> short-circuit without issuing SOQL.
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        // Build the Id literal list for the IN clause. Values come from a Set<Id> so they
        // are guaranteed valid, well-formed Id tokens; quoting makes the literal unambiguous
        // in dynamic SOQL. (The Set already removes duplicates.)
        List<String> idLiterals = new List<String>();
        for (Id accountId : accountIds) {
            idLiterals.add('\'' + String.valueOf(accountId) + '\'');
        }

        fflib_QueryFactory queryFactory = newQueryLocator();
        queryFactory.selectField('Account.Name');
        queryFactory.whereClause('IsClosed = false');
        queryFactory.whereClause('AccountId IN (' + String.join(idLiterals, ',') + ')');
        // Highest Amount first; null Amounts placed last; ties broken by earliest CloseDate.
        queryFactory.orderBy('Amount DESC NULLS LAST').orderBy('CloseDate ASC');
        queryFactory.limit(String.valueOf(maxRecords));

        return (List<Opportunity>) queryFactory.query();
    }
}
