public class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> newAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new Schema.SObjectType[] {
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acct = new Account(Name = accountName);
            uow.registerNew(acct);
            newAccounts.add(acct);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    Contact con = new Contact(LastName = lastName, AccountId = acct.Id);
                    // Setting AccountId to an in-memory SObject reference works because
                    // the UoW inserts Accounts before Contacts (dependency order).
                    // However, for in-memory references we set the field to the SObject instance:
                    con.AccountId = null; // reset to avoid issues, rely on relationship resolution below
                    // Actually, fflib handles this via registerNew(sObject) if we set the field
                    // to the SObject instance directly. Let's just assign it:
                    con.AccountId = acct.Id; // This won't be populated yet, so we must rely on
                    // setting it as an SObject reference. But AccountId is an Id field.
                    // The correct fflib pattern is to set the relationship to the SObject instance:
                    // Actually, standard Apex allows assigning an SObject to a lookup field if it's
                    // a relationship field (e.g. Account). But Contact.AccountId is an Id field.
                    // So we can't assign acct to con.AccountId directly as an Id.
                    // fflib_SObjectUnitOfWork doesn't have registerNew(sObject, sObject).
                    // The standard pattern is:
                    // 1. registerNew(acct)
                    // 2. registerNew(con)
                    // 3. After commit, the IDs are populated. But during commit, we need the link.
                    // Actually, setting con.Account = acct works (relationship field).
                    con.Account = acct;
                    uow.registerNew(con);
                }
            }
        }

        uow.commitWork();

        return newAccounts;
    }
}
