/**
 * ErpCustomerSync
 *
 * Pushes new Accounts to the ERP as customer records.
 *
 * Endpoint : POST callout:ERP/api/customers
 * Body     : [{"salesforceId":"001…","name":"…","country":"…"}]
 * Response : 202 Accepted (error handling / retries out of scope)
 *
 * Synchronous callouts are forbidden after DML, so each HTTP POST is
 * performed inside @future(callout=true).  A single Account yields one
 * future and one request; marketplace batches of up to 200 fan out
 * into 4 futures of 50 Accounts each, keeping us within the 50-callout
 * ceiling per future.
 */
public with sharing class ErpCustomerSync {

    /* ------------------------------------------------------------------ */
    //  Constants
    /* ------------------------------------------------------------------ */
    private static final String  ENDPOINT    = 'callout:ERP/api/customers';

    /** Callout ceiling per @future execution. */
    private static final Integer CHUNK_SIZE  = 50;

    /* ------------------------------------------------------------------ */
    //  Public entry point – called from the trigger
    /* ------------------------------------------------------------------ */
    public static void enqueue(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<String> ids = new List<String>();
        for (Account acc : newAccounts) {
            ids.add(acc.Id);
        }

        // Slice into chunks of 50 so each @future stays within the
        // callout ceiling.
        for (Integer i = 0; i < ids.size(); i += CHUNK_SIZE) {
            Integer to = Math.min(i + CHUNK_SIZE, ids.size());
            pushAccountsFuture(ids.subList(i, to));
        }
    }

    /* ------------------------------------------------------------------ */
    //  Async worker
    /* ------------------------------------------------------------------ */
    @future(callout=true)
    public static void pushAccountsFuture(List<String> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM   Account
            WHERE  Id IN :accountIds
        ];

        Http http = new Http();

        for (Account acc : accounts) {
            String country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;

            HttpRequest req = new HttpRequest();
            req.setMethod('POST');
            req.setEndpoint(ENDPOINT);
            req.setHeader('Content-Type', 'application/json');
            req.setBody(buildBody(acc.Id, acc.Name, country));

            HttpResponse resp = http.send(req);

            // 202 Accepted is the expected response. Error handling /
            // retries are explicitly out of scope for this ticket; we
            // only log unexpected status codes for observability.
            if (resp.getStatusCode() < 200 || resp.getStatusCode() >= 300) {
                System.debug(LoggingLevel.WARN,
                    'ErpCustomerSync: unexpected status ' + resp.getStatusCode()
                    + ' for Account ' + acc.Id);
            }
        }
    }

    /* ------------------------------------------------------------------ */
    //  Body construction
    /* ------------------------------------------------------------------ */
    /**
     * Serialise a one-element JSON array. JSONGenerator is used so that
     * a null country is emitted as `"country": null` rather than being
     * dropped by JSON.serialize.
     */
    private static String buildBody(Id salesforceId, String name, String country) {
        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartArray();
        gen.writeStartObject();
        gen.writeStringField('salesforceId', salesforceId);
        gen.writeStringField('name', name);
        if (country == null) {
            gen.writeNullField('country');
        } else {
            gen.writeStringField('country', country);
        }
        gen.writeEndObject();
        gen.writeEndArray();
        return gen.getAsString();
    }
}
