public class FollowUpTaskService {
    /**
     * Creates a follow-up Task for each Opportunity provided.
     * Uses Database.insert(list, false) so that a validation-rule rejection
     * on one Task does not prevent the remaining Tasks from being created.
     *
     * @param  opportunityIds  list of Opportunity Ids that came out of the
     *                          weekly pipeline review.
     * @return Set<Id>          Opportunity Ids whose Task could NOT be created.
     *                          Empty set when every Task succeeded.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOppIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOppIds;
        }

        // Single SOQL to retrieve Name and OwnerId – avoids a query inside the loop.
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId
            FROM   Opportunity
            WHERE  Id IN :opportunityIds
        ];

        // Build the full list of Tasks first, then insert in one DML statement
        // with partial-success mode so a VR rejection on one record does not
        // stop the others.
        List<Task> tasksToInsert = new List<Task>();
        List<Id>   oppIdOrder    = new List<Id>();   // parallel index for mapping

        for (Opportunity opp : opportunities) {
            Task t = new Task();
            t.WhatId       = opp.Id;
            t.OwnerId      = opp.OwnerId;
            t.Subject      = 'Follow up: ' + opp.Name;
            t.ActivityDate = Date.today().addDays(7);
            t.Status       = 'Not Started';
            t.Priority     = 'Normal';

            tasksToInsert.add(t);
            oppIdOrder.add(opp.Id);
        }

        // Single DML – no limit issue even at 250+ records.
        Database.SaveResult[] results = Database.insert(tasksToInsert, false);

        // Inspect each result; collect the Opportunity Id for any failure.
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                // Log the first error message for diagnosis.
                String errMsg = '';
                if (results[i].hasErrors()) {
                    Database.Error firstErr = results[i].getErrors()[0];
                    errMsg = firstErr.getMessage();
                }
                System.debug(LoggingLevel.ERROR,
                    'FollowUpTaskService: failed to create Task for Opportunity ' +
                    oppIdOrder[i] + ' – ' + errMsg);

                failedOppIds.add(oppIdOrder[i]);
            }
        }

        return failedOppIds;
    }
}
