public with sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    @future
    public static void recalculate(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) return;

        List<Opportunity> opps = [
            SELECT AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
        ];

        Map<Id, Decimal> maxAmounts = new Map<Id, Decimal>();
        Map<Id, Boolean> hasOpen   = new Map<Id, Boolean>();
        for (Id accId : accountIds) {
            maxAmounts.put(accId, null);
            hasOpen.put(accId, false);
        }

        for (Opportunity opp : opps) {
            hasOpen.put(opp.AccountId, true);
            if (opp.Amount != null) {
                Decimal current = maxAmounts.get(opp.AccountId);
                if (current == null || opp.Amount > current) {
                    maxAmounts.put(opp.AccountId, opp.Amount);
                }
            }
        }

        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountIds) {
            String rating;
            if (!hasOpen.get(accId)) {
                rating = 'Cold';
            } else {
                Decimal max = maxAmounts.get(accId);
                rating = (max != null && max >= HOT_THRESHOLD) ? 'Hot' : 'Warm';
            }
            toUpdate.add(new Account(Id = accId, Rating = rating));
        }
        update toUpdate;
    }
}
