```apex
public with sharing class RenewalReminderService {

    /**
     * Sends a renewal reminder email to each opportunity's owner.
     *
     * @param opportunityIds IDs of the opportunities whose owners should be
     *                       reminded.  Pass up to 200 IDs per call.
     * @return the number of emails that were accepted by the messaging gateway
     */
    public static Integer sendReminders(List<Id> opportunityIds) {

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Defensive guard – the caller promises ≤ 200 IDs per invocation.
        if (opportunityIds.size() > 200) {
            throw new IllegalArgumentException(
                'sendReminders accepts at most 200 opportunity Ids per call; received '
                + opportunityIds.size()
            );
        }

        // Bulk-safe: single SOQL, no query inside any loop.
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>();
        for (Opportunity opp : [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]) {
            oppMap.put(opp.Id, opp);
        }

        // Build every message first.  A single Messaging.sendEmail call with
        // the full list counts as ONE email invocation, keeping us well within
        // the 10-invocation governor limit even for 200 opportunities.
        List<Messaging.SingleEmailMessage> messages =
            new List<Messaging.SingleEmailMessage>();
        List<Id> validOpportunityIds = new List<Id>();  // track for result mapping

        for (Id oppId : opportunityIds) {

            Opportunity opp = oppMap.get(oppId);
            if (opp == null) {
                // Deleted between SOQL and now – skip silently.
                continue;
            }

            // setTargetObjectId requires a User (or Contact/Lead) Id.
            // If OwnerId is a Group the send will fail; that failure is
            // isolated per-result so other opportunities still send.
            if (opp.OwnerId == null) {
                System.debug(LoggingLevel.WARN,
                    'RenewalReminderService: Opportunity ' + opp.Id +
                    ' has no owner – skipping.');
                continue;
            }

            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);
            mail.setPlainTextBody(
                'A reminder that the opportunity "' + opp.Name +
                '" has a close date of ' + opp.CloseDate.format() + '. ' +
                'Please review and take action before the renewal deadline.'
            );

            messages.add(mail);
            validOpportunityIds.add(opp.Id);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        // Single invocation – result array is parallel to the input list.
        Integer sentCount = 0;

        Messaging.SendEmailResult[] results =
            Messaging.sendEmail(messages);

        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                sentCount++;
            }
        }

        return sentCount;
    }
}
