            return;
        }
        this.items = [...this.items, { id: `new-${this.nextId++}`, label, done: false }];
        this.newLabel = '';
        this.dispatchEvent(
            new CustomEvent('taskadded', {
                detail: { label },
                bubbles: true,
                composed: true
            })
        );
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        if (id == null) {
            return;
        }
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
