/**
 * GiftImportService
 *
 * Replaces the website integration's direct Contact/Opportunity inserts with
 * NPSP's own data import pipeline. Each incoming {@link WebGift} is staged as
 * an npsp__DataImport__c row, then the staged rows are processed synchronously
 * in the same transaction by invoking NPSP's Apex data import API. Because the
 * org's Data_Import_Settings__c hierarchy setting is the source of truth for
 * matching rules, we do not mutate it here — NPSP's engine reads it for us.
 *
 * Guarantees:
 *   - One ImportResult per input gift, in input order.
 *   - A failure of any single row never aborts the rest (Database.insert uses
 *     allOrNone=false, and NPSP records per-row FailureInformation for rows it
 *     rejects inside its processor).
 *   - A null/empty input list returns an empty list.
 *   - 200 gifts fit comfortably in a single transaction.
 */
public with sharing class GiftImportService {

    /**
     * One-off gift captured from the website.
     */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    /**
     * Outcome of importing a single WebGift.
     */
    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    // NPSP's Donation_Donor picklist value used when the gift is associated
    // with Contact1 (matching is driven by First/Last/Email per org setting).
    private static final String DONOR_CONTACT1 = 'Contact1';

    // Status string NPSP writes when the row was successfully processed.
    private static final String STATUS_IMPORTED = 'Imported';

    /**
     * Entry point: stage every gift as a Data Import record and let NPSP's
     * engine run its match / create / household rules synchronously.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // ---- 1. Stage one npsp__DataImport__c row per gift -----------------
        List<npsp__DataImport__c> staged = stage(gifts);

        // ---- 2. Persist the staging records, tolerant of bad rows ----------
        // allOrNone=false keeps a single malformed row from rolling back the
        // whole batch; the per-row SaveResult is what we surface in step 4.
        List<Database.SaveResult> saveResults = Database.insert(staged, false);

        Set<Id> stagedIds = new Set<Id>();
        for (npsp__DataImport__c row : staged) {
            if (row.Id != null) {
                stagedIds.add(row.Id);
            }
        }

        // ---- 3. Hand staged rows to NPSP's synchronous import API ----------
        // npsp.DataImportService is the Apex entry point for the same engine
        // the batched "Run Data Import" button uses. It reads the org's
        // npsp__Data_Import_Settings__c hierarchy setting (here: match by
        // First/Last/Email, never match an existing donation) and writes back
        // Contact1Imported, DonationImported, Status, FailureInformation.
        if (!stagedIds.isEmpty()) {
            npsp.DataImportService.process(stagedIds);
        }

        // ---- 4. Read back post-import state in a single SOQL ---------------
        Map<Id, npsp__DataImport__c> post = readBack(stagedIds);

        // ---- 5. Compose results in input order -----------------------------
        return compose(gifts.size(), staged, saveResults, post);
    }

    // ------------------------------------------------------------------------
    // Internal helpers
    // ------------------------------------------------------------------------

    private static List<npsp__DataImport__c> stage(List<WebGift> gifts) {
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>(gifts.size());
        for (WebGift g : gifts) {
            npsp__DataImport__c row = new npsp__DataImport__c();
            row.npsp__Contact1_Firstname__c      = g.firstName;
            row.npsp__Contact1_Lastname__c       = g.lastName;
            row.npsp__Contact1_Personal_Email__c = g.email;
            row.npsp__Donation_Amount__c         = g.amount;
            row.npsp__Donation_Date__c           = g.giftDate;
            // Route the donation to Contact1 so NPSP applies its contact match
            // rules; the alternative Account1 path would bypass the configured
            // person-matching behaviour we depend on.
            row.npsp__Donation_Donor__c          = DONOR_CONTACT1;
            staged.add(row);
        }
        return staged;
    }

    private static Map<Id, npsp__DataImport__c> readBack(Set<Id> ids) {
        Map<Id, npsp__DataImport__c> byId = new Map<Id, npsp__DataImport__c>();
        if (ids.isEmpty()) {
            return byId;
        }
        for (npsp__DataImport__c row : [
                SELECT Id,
                       npsp__Status__c,
                       npsp__FailureInformation__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c
                FROM   npsp__DataImport__c
                WHERE  Id IN :ids
              ]) {
            byId.put(row.Id, row);
        }
        return byId;
    }

    private static List<ImportResult> compose(
            Integer inputSize,
            List<npsp__DataImport__c> staged,
            List<Database.SaveResult> saveResults,
            Map<Id, npsp__DataImport__c> post) {

        List<ImportResult> results = new List<ImportResult>(inputSize);
        for (Integer i = 0; i < inputSize; i++) {
            results.add(new ImportResult());
        }

        for (Integer i = 0; i < staged.size(); i++) {
            ImportResult ir = results[i];

            // (a) The staging DML itself failed for this row.
            if (!saveResults[i].isSuccess()) {
                ir.success = false;
                ir.errorMessage = describeSaveError(saveResults[i]);
                continue;
            }

            // (b) Row was persisted but NPSP couldn't find it during processing
            //     (defensive — shouldn't happen, but cheap to handle).
            npsp__DataImport__c di = post.get(staged[i].Id);
            if (di == null) {
                ir.success = false;
                ir.errorMessage = 'NPSP Data Import record was not found after processing.';
                continue;
            }

            // (c) NPSP reported success and linked a donation.
            if (di.npsp__Status__c == STATUS_IMPORTED && di.npsp__DonationImported__c != null) {
                ir.success = true;
                ir.contactId = di.npsp__Contact1Imported__c;
                ir.opportunityId = di.npsp__DonationImported__c;
            } else {
                // (d) NPSP failed this row; surface its FailureInformation as-is
                //     so the integration team sees exactly what NPSP complained
                //     about, while leaving the rest of the batch untouched.
                ir.success = false;
                ir.errorMessage = di.npsp__FailureInformation__c != null
                    ? di.npsp__FailureInformation__c
                    : 'NPSP Data Import did not import the row (Status=' + di.npsp__Status__c + ').';
            }
        }

        return results;
    }

    private static String describeSaveError(Database.SaveResult sr) {
        List<Database.Error> errs = sr.getErrors();
        if (errs == null || errs.isEmpty()) {
            return 'Failed to stage NPSP Data Import record.';
        }
        Database.Error e = errs.get(0);
        return e.getStatusCode() + ': ' + e.getMessage();
    }
}
