public with sharing class HouseholdService {

    /**
     * Creates a single NPSP household account for the supplied contacts.
     *
     * @param  members   New contacts to be inserted under one household.
     *                   The first element becomes the household primary contact.
     * @return           Id of the newly created household Account.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members list must not be null or empty');
        }

        // Resolve the Household Account record-type Id without hard-coding.
        Id householdRTId = (Id) [
            SELECT Id
            FROM RecordType
            WHERE SobjectType  = 'Account'
              AND DeveloperName = 'HH_Account'
            LIMIT 1
        ].Id;

        // ── 1. Create the household account ──────────────────────────────
        // Name is required by the platform, but NPSP's automatic household
        // naming (AccountHandler / ContactHandler) will overwrite it once
        // contacts are linked.  We deliberately do NOT construct a name.
        Account household = new Account(
            RecordTypeId = householdRTId,
            Name         = 'Household'   // placeholder – NPSP will replace it
        );
        insert household;

        // ── 2. Insert every contact under this single household ──────────
        List<Contact> newContacts = new List<Contact>(members.size());
        for (Contact c : members) {
            c.AccountId = household.Id;
            newContacts.add(c);
        }
        insert newContacts;

        // ── 3. Promote the first contact as the household primary contact ─
        // Setting npe01__One2OneContact__c also triggers NPSP greeting /
        // name generation, so the placeholder Name is overwritten.
        household.npe01__One2OneContact__c = newContacts[0].Id;
        update household;

        return household.Id;
    }
}
