public class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // Null or empty input does nothing
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Collect IDs and validate no duplicate opp/contact pairs
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> pairKeys = new Set<String>();

        for (SoftCreditRequest req : requests) {
            String pairKey = String.valueOf(req.opportunityId) + '|' + String.valueOf(req.contactId);
            if (pairKeys.contains(pairKey)) {
                throw new SoftCreditException('Duplicate opportunity/contact pair in request: ' + pairKey);
            }
            pairKeys.add(pairKey);
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // SOQL 1: Opportunities for amounts and primary contact
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>();
        for (Opportunity opp : [
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]) {
            oppMap.put(opp.Id, opp);
        }

        // Validate before any DML
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c != null && opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException('Contact is the primary contact on the opportunity.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive and non-null.');
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException('Amount exceeds the opportunity amount.');
            }
        }

        // SOQL 2: Existing OpportunityContactRoles
        Map<String, OpportunityContactRole> existingOcrMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            String key = String.valueOf(ocr.OpportunityId) + '|' + String.valueOf(ocr.ContactId) + '|' + ocr.Role;
            existingOcrMap.put(key, ocr);
        }

        // Determine which OCRs need to be created
        List<OpportunityContactRole> newOcrs = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> resolvedOcrMap = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String ocrKey = String.valueOf(req.opportunityId) + '|'
                          + String.valueOf(req.contactId) + '|' + req.role;
            if (existingOcrMap.containsKey(ocrKey)) {
                resolvedOcrMap.put(ocrKey, existingOcrMap.get(ocrKey));
            } else {
                OpportunityContactRole ocr = new OpportunityContactRole();
                ocr.OpportunityId = req.opportunityId;
                ocr.ContactId = req.contactId;
                ocr.Role = req.role;
                newOcrs.add(ocr);
                resolvedOcrMap.put(ocrKey, ocr);
            }
        }

        // DML 1: Insert new OpportunityContactRoles
        if (!newOcrs.isEmpty()) {
            insert newOcrs;
        }

        // SOQL 3: Existing Partial Soft Credits
        Map<String, npsp__Partial_Soft_Credit__c> existingPscMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            String key = String.valueOf(psc.npsp__Opportunity__c) + '|' + String.valueOf(psc.npsp__Contact__c);
            existingPscMap.put(key, psc);
        }

        // Build Partial Soft Credit records
        List<npsp__Partial_Soft_Credit__c> newPscs = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> updatePscs = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String pairKey = String.valueOf(req.opportunityId) + '|' + String.valueOf(req.contactId);
            String ocrKey = String.valueOf(req.opportunityId) + '|' + String.valueOf(req.contactId) + '|' + req.role;
            OpportunityContactRole ocr = resolvedOcrMap.get(ocrKey);

            if (existingPscMap.containsKey(pairKey)) {
                // Update existing partial soft credit
                npsp__Partial_Soft_Credit__c psc = existingPscMap.get(pairKey);
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
                updatePscs.add(psc);
            } else {
                // Create new partial soft credit
                npsp__Partial_Soft_Credit__c psc = new npsp__Partial_Soft_Credit__c();
                psc.npsp__Opportunity__c = req.opportunityId;
                psc.npsp__Contact__c = req.contactId;
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
                psc.npsp__Contact_Name__c = req.contactId;
                newPscs.add(psc);
            }
        }

        // DML 2: Insert new Partial Soft Credits
        if (!newPscs.isEmpty()) {
            insert newPscs;
        }

        // DML 3: Update existing Partial Soft Credits
        if (!updatePscs.isEmpty()) {
            update updatePscs;
        }
    }
}
