public class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {

        // ── Validate inputs ──────────────────────────────────────────────
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('Contact ID must not be null.');
        }

        // ── Fetch donor contact (also validates existence) ───────────────
        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        Contact donor = donors[0];
        Id householdAccountId = donor.AccountId;

        // ── Build Opportunity name ───────────────────────────────────────
        String name = donor.FirstName + ' ' + donor.LastName
                    + ' Donation ' + String.valueOf(giftDate);

        // ── Insert Closed-Won Opportunity ────────────────────────────────
        // Setting npsp__Primary_Contact__c causes NPSP to auto-create
        // the "Donor" ContactRole for the primary contact.
        Opportunity opp = new Opportunity(
            AccountId                = householdAccountId,
            Name                     = name,
            StageName                = 'Closed Won',
            CloseDate                = giftDate,
            Amount                   = amount,
            npsp__Primary_Contact__c = contactId
        );
        insert opp;

        // ── Contact Roles: other household members get "Household Member" ─
        // The donor's "Donor" role is already created by NPSP via the
        // Primary Contact field, so we only add roles for the remaining members.
        List<Contact> household = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdAccountId
        ];

        List<OpportunityContactRole> roles = new List<OpportunityContactRole>();
        for (Contact c : household) {
            if (c.Id != contactId) {
                roles.add(new OpportunityContactRole(
                    OpportunityId = opp.Id,
                    ContactId     = c.Id,
                    Role          = 'Household Member'
                ));
            }
        }
        if (!roles.isEmpty()) {
            insert roles;
        }

        // ── Single paid payment for the full amount ──────────────────────
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c    = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c   = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c           = true
        );
        insert payment;

        return opp.Id;
    }
}
