/**
 * Bulk service for reassigning Account (and related Contact) ownership.
 *
 * • Account trigger actions are bypassed for the entire Account sObject so the
 *   (expensive) territory-recalculation actions do NOT fire.
 * • Contact trigger actions run normally.
 * • The Account bypass is guaranteed to be cleared in a finally block, whether
 *   the method succeeds or throws.
 * • Uses all-or-none DML; any exception propagates uncaught to the caller.
 * • At most 2 SOQL and 2 DML regardless of record volume (≤ 200 accounts).
 */
public with sharing class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        try {
            // ── 1. Bypass ALL Account trigger actions ──────────────────────────
            TriggerBase.bypass('Account');

            // ── 2. Build Account records (no SOQL needed – Ids already known) ──
            List<Account> accounts = new List<Account>();
            for (Id acctId : accountIds) {
                accounts.add(new Account(Id = acctId, OwnerId = newOwnerId));
            }
            update accounts;          // DML #1  (all-or-none by default)

            // ── 3. Query Contacts belonging to these Accounts (1 SOQL) ────────
            List<Contact> contacts = [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :accountIds
            ];

            // ── 4. Set Contact OwnerId and update (triggers run normally) ─────
            for (Contact c : contacts) {
                c.OwnerId = newOwnerId;
            }
            if (!contacts.isEmpty()) {
                update contacts;      // DML #2  (all-or-none by default)
            }

        } finally {
            // Regardless of success or exception, Account automation resumes.
            TriggerBase.clearBypass('Account');
        }
    }
}
