```apex
/**
 * Trigger action that maintains Account.FB_Open_Case_Count__c, the number of the
 * account's Cases with IsClosed = false.
 *
 * Registers against Case for after insert / update / delete / undelete via the
 * Trigger Actions Framework (unlocked, no namespace).
 *
 * Design notes / limits:
 *  - Exactly ONE SOQL query and ONE DML statement per trigger execution.
 *  - Bulk-safe: works for up to 200 cases per operation.
 *  - Affected accounts = distinct (new ∪ old) AccountIds of the rows touched in
 *    this context. The current open-case count is recomputed from the database,
 *    so created / closed / reopened / moved / deleted / undeleted cases are all
 *    handled by the same code path.
 *  - Accounts whose last open case disappears are written with 0 (not blank).
 *  - Cases without an Account are ignored.
 */
public with sharing class TA_Case_RollupOpenCount
        implements TriggerAction.AfterInsert,
                   TriggerAction.AfterUpdate,
                   TriggerAction.AfterDelete,
                   TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(extractAccountIds(triggerNew));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        // An Account can change, so union new and old AccountIds.
        Set<Id> affected = new Set<Id>();
        affected.addAll(extractAccountIds(triggerNew));
        affected.addAll(extractAccountIds(triggerOld));
        recalculate(affected);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(extractAccountIds(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(extractAccountIds(triggerNew));
    }

    /**
     * Collect distinct AccountIds from a list of Case records, skipping the
     * records that have no Account (null AccountId).
     */
    private static Set<Id> extractAccountIds(List<SObject> cases) {
        Set<Id> accountIds = new Set<Id>();
        if (cases == null) {
            return accountIds;
        }
        for (SObject rec : cases) {
            Id accId = (Id) rec.get('AccountId');
            if (accId != null) {
                accountIds.add(accId);
            }
        }
        return accountIds;
    }

    /**
     * For each affected account, recompute its open case count from the database
     * and update it in a single bulk DML. Accounts that no longer have any open
     * case are explicitly set to 0.
     *
     * Uses at most one SOQL query and one DML statement.
     */
    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // ONE SOQL query: open case counts grouped by account, restricted to
        // the affected accounts. Accounts with zero open cases are absent here,
        // which is handled by defaulting to 0 below.
        Map<Id, Integer> openCounts = new Map<Id, Integer>();
        for (AggregateResult ar : [
                SELECT AccountId, COUNT(Id) cnt
                FROM Case
                WHERE AccountId IN :accountIds
                    AND IsClosed = false
                GROUP BY AccountId
            ]) {
            Id accId = (Id) ar.get('AccountId');
            Integer cnt = (Integer) ar.get('cnt');
            openCounts.put(accId, cnt);
        }

        // ONE DML statement: write the new count for every affected account,
        // including those whose count is now 0.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Integer newCount = openCounts.containsKey(accId) ? openCounts.get(accId) : 0;
            accountsToUpdate.add(new Account(Id = accId, FB_Open_Case_Count__c = newCount));
        }
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
